(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:''};
  async function api(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('../../../api/vendor/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Unable to load your store.');return data;}
  function notice(text,error=false){el('vs-status').textContent=text;el('vs-status').className='vc-status '+(error?'warning':'info');}
  function fill(form,data){Object.entries(data||{}).forEach(([name,value])=>{const field=form.elements.namedItem(name);if(!field)return;if(field.type==='checkbox')field.checked=Boolean(Number(value));else field.value=value??'';});}
  function policies(data){const wrap=el('vs-policies');wrap.replaceChildren();const labels={return_policy:'Returns and replacements',cancellation_policy:'Cancellations',damage_policy:'Damage or missing items',handmade_policy:'Handmade variation and care',materials_sourcing:'Materials and sourcing',packaging_approach:'Packaging',maker_payment_model:'Maker payments'};let count=0;Object.entries(labels).forEach(([key,label])=>{if(!data?.[key])return;count++;const section=document.createElement('div');section.className='vc-list-item';const title=document.createElement('strong');title.textContent=label;const body=document.createElement('p');body.textContent=data[key];section.append(title,body);wrap.append(section);});if(!count)wrap.textContent='Policies are not available yet. Complete onboarding first.';}
  async function load(){try{const [identity,result]=await Promise.all([api('auth/me.php'),api('store-profile.php')]);state.csrf=identity.csrf_token||'';fill(el('vs-store'),result.store);fill(el('vs-dispatch'),result.dispatch_address);policies(result.policies);notice('Store profile loaded.');}catch(error){notice(error.message,true);}}
  ['vs-store','vs-dispatch'].forEach(id=>el(id).addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const body=Object.fromEntries(new FormData(form));body.section=id==='vs-store'?'store':'dispatch';if(body.section==='store')body.is_public=form.elements.namedItem('is_public').checked;const button=event.submitter;button.disabled=true;try{await api('store-profile.php','PATCH',body);notice(body.section==='store'?'Store profile saved.':'Dispatch address saved.');}catch(error){notice(error.message,true);}finally{button.disabled=false;}}));
  load();
})();
